import{F as e,I as t,Z as n,t as r}from"./chunks/framework.CJzTmXUT.js";var i=JSON.parse(`{"title":"File Tree Component","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/file-tree.md","filePath":"en/deep-dive/file-tree.md","lastUpdated":1793283054000}`),a={name:`deep-dive/file-tree.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="file-tree-component" tabindex="-1">File Tree Component <a class="header-anchor" href="#file-tree-component" aria-label="Permalink to “File Tree Component”">​</a></h1><p>File tree is a SolidJS component that visualizes an array of sync tasks, and enables selecting / deselecting tasks.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How It Works”">​</a></h2><p>Creates visual hierarchy (left padding) for different folder nesting levels.</p><p>Renders select box, Obsidian tooltip, icon, and task path</p><p>1 universal path compaction rule:</p><ul><li>if a folder only has one children in the task list, and the folder itself is not in the task list, the children and folder combines into one entry with path shown as <code>&lt;parent-basename&gt; / &lt;child-basename&gt;</code>. This applies to each two path segments, so continuous nesting chains can be joined continuously, only stop at shallowest common parent.</li></ul><p>8 input validation rules:</p><ul><li>Deselecting any direct children delete task deselects parent delete.</li><li>Selecting parent delete task selects all direct children delete tasks.</li><li>Deselecting folder creation tasks deselects all direct children creation tasks.</li><li>Selecting any children creation tasks selects its parent creation.</li><li>All the four rules above cascade propagate.</li><li><code>Move</code> tasks are equal to creation tasks in validation logic.</li><li>Convert a <code>Move</code> task into a <code>CreateDir</code> task if any direct child <code>Move</code> tasks is deselected or converted to a <code>CreateDir</code> task.</li><li>Convert a <code>CreateDir</code> into a <code>Move</code> task if it was previously converted from a <code>Move</code> task and all its direct children are selected <code>Move</code> tasks.</li></ul><p>Behavior: selecting / unselecting only, no collapsing, no expansion.</p><p>Select all / deselect all:</p><ul><li>This option is rendered in style similar to a normal tree node with a checkbox icon <code>folders</code>, and corresponding state text <code>selectAll</code> or <code>deselectAll</code>, positioned like a root node in the tree, above all task nodes.</li><li>When any of the tasks is selected, the action should be <code>deselectAll</code>. Only when none of the tasks is selected, action is <code>selectAll</code>.</li><li>The checkbox should show indeterminate state when tasks are partially selected, otherwise show checked / unchecked.</li></ul><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to “Implementation”">​</a></h2><ol><li>Pre-process:</li></ol><p>First, build a prefix tree from the array of task paths. Then, run a recursive &quot;compact&quot; function that merges single-child folders.</p><ol start="2"><li>Rendering and input validation:</li></ol><p>Flatten the compacted tree into a 1D array, and store it in a <code>Record</code> object. The cascade logic is handled by a pure function that triggers on tasks selection and deselection.</p><p>The UI simply maps over the flat array and applies padding-left based on the depth property.</p>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};